Copy the workbook, read the cached values from `RateHurdles` and `Deposits`, then scan `RateHurdles` in row order for the first row matching type, salesperson, and a date range containing the deposit date. Write the matched rate as a plain value into `Deposits!A2:A3`.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

rate_ws = vals["RateHurdles"]
dep_ws = vals["Deposits"]
out_ws = wb["Deposits"]

def to_datetime(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return datetime(1899, 12, 30) + timedelta(days=float(value))

    s = str(value).strip()
    formats = (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%m/%d/%Y %H:%M:%S",
        "%m/%d/%Y",
    )
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None

for r in range(2, dep_ws.max_row + 1):
    dep_type = dep_ws.cell(row=r, column=2).value
    dep_person = dep_ws.cell(row=r, column=3).value
    dep_date = to_datetime(dep_ws.cell(row=r, column=4).value)

    if dep_type is None or dep_person is None or dep_date is None:
        out_ws.cell(row=r, column=1).value = None
        continue

    dep_type_s = str(dep_type).strip()
    dep_person_s = str(dep_person).strip()
    found_rate = None

    for rr in range(2, rate_ws.max_row + 1):
        start = to_datetime(rate_ws.cell(row=rr, column=1).value)
        end = to_datetime(rate_ws.cell(row=rr, column=2).value)
        rate_type = rate_ws.cell(row=rr, column=3).value
        rate_person = rate_ws.cell(row=rr, column=4).value
        rate = rate_ws.cell(row=rr, column=5).value

        if rate_type is None or rate_person is None or start is None or end is None:
            continue

        if (
            str(rate_type).strip() == dep_type_s
            and str(rate_person).strip() == dep_person_s
            and start <= dep_date <= end
        ):
            found_rate = rate
            break

    if found_rate is None:
        out_ws.cell(row=r, column=1).value = None
    else:
        try:
            out_ws.cell(row=r, column=1).value = float(found_rate)
        except (TypeError, ValueError):
            out_ws.cell(row=r, column=1).value = found_rate

    print(f"Deposits row {r}: {dep_type_s} | {dep_person_s} | {dep_date} -> {found_rate}")

wb.save(OUT)
